   RAISE EXCEPTION 'Expected 10 active instructor-final templates';
 END IF;
 IF EXISTS (SELECT 1 FROM public.feedback_template_versions v JOIN public.feedback_templates t ON t.id=v.template_id JOIN public.feedback_programs p ON p.key=t.program_key AND p.is_active WHERE t.audience='instructor' AND t.stage='final' AND v.status='draft') THEN
   RAISE EXCEPTION 'Existing instructor-final draft detected. Preserve and review it before proceeding.';
 END IF;
 FOR v_t IN SELECT t.id AS template_id,t.program_key FROM public.feedback_templates t JOIN public.feedback_programs p ON p.key=t.program_key AND p.is_active WHERE t.audience='instructor' AND t.stage='final' ORDER BY t.program_key LOOP
   INSERT INTO public.feedback_template_versions(template_id,version_no,status,intro_text,intro_text_ar,notes)
   SELECT v_t.template_id,coalesce(max(v.version_no),0)+1,'draft',
      'מדריכות ומדריכים יקרים, נשמח ללמוד מניסיונכם בהדרכת הקורס בפועל. מטרת המשוב היא לזהות מה איכותי ועובד היטב בתוכן, במצגות ובפעילויות, ומה כדאי לתקן, לדייק, להנגיש או לשנות. שאלות הדירוג מתייחסות לניסיון שלכם בכיתה, ולא להערכת ביצועיכם כמדריכים. בשאלות סימון ניתן לבחור כמה אפשרויות; אם אין נושא מתאים, אפשר להשאיר אותן ללא סימון. בסיום תוצע לכם אפשרות להקדיש כחמש דקות נוספות להמלצות מפורטות. תודה על השותפות!',
      'المرشدات والمرشدون الأعزاء، نود أن نتعلّم من خبرتكم العملية في إرشاد الدورة. يهدف الاستبيان إلى معرفة ما ينجح في المحتوى والعروض والأنشطة، وما يحتاج إلى تصحيح أو تدقيق أو تبسيط أو تغيير. أسئلة التقييم تتعلق بتجربتكم في الصف، وليست تقييمًا لأدائكم كمرشدين. في أسئلة الاختيار المتعدد يمكن تحديد عدة خيارات، ويمكن تركها فارغة إذا لم يكن هناك ما ينطبق. في النهاية سنعرض عليكم إمكانية تخصيص نحو خمس دقائق إضافية لتقديم توصيات مفصلة. شكرًا على تعاونكم!',
      'טיוטת שלב 2: הערכה מקצועית של איכות הקורס, התוכן, המצגות והפעילויות; 3 שאלות לפי סילבוס. אין פרסום. שאלות המשך מותנות בשלב 3.'
   FROM public.feedback_template_versions v WHERE v.template_id=v_t.template_id RETURNING id INTO v_version;
   FOR v_item IN SELECT value FROM jsonb_array_elements(v_payload) LOOP
     v_program_key := nullif(v_item->>'program','');
     IF v_program_key IS NOT NULL AND v_program_key <> v_t.program_key THEN CONTINUE; END IF;
     v_question_key := 'in_final_20261013_'||(v_item->>'key');
     INSERT INTO public.feedback_questions(question_key,program_key,metric_key,question_type,audiences,stages,is_comparison,wording,options,scoring,default_required,sort_order)
     VALUES(v_question_key,v_program_key,v_item->>'metric',v_item->>'type',ARRAY['instructor']::text[],ARRAY['final']::text[],false,
       jsonb_build_object('default',v_item->>'he','ar',v_item->>'ar'),coalesce(v_item->'opt','[]'::jsonb),
       jsonb_build_object('include_in_score',(v_item->>'type'='rating_1_5'),'allow_na',coalesce((v_item->>'na')::boolean,false)),
       (v_item->>'required')::boolean,(v_item->>'n')::integer)
     ON CONFLICT (question_key) DO NOTHING;
     SELECT id INTO STRICT v_qid FROM public.feedback_questions WHERE question_key=v_question_key;
     INSERT INTO public.feedback_template_questions(version_id,question_id,section,sort_order,required,metric_key,question_type,is_comparison,wording,options,scoring)
     VALUES(v_version,v_qid,v_item->>'section',(v_item->>'n')::integer,(v_item->>'required')::boolean,
       v_item->>'metric',v_item->>'type',false,jsonb_build_object('default',v_item->>'he','ar',v_item->>'ar'),
       coalesce(v_item->'opt','[]'::jsonb),
       jsonb_build_object('include_in_score',(v_item->>'type'='rating_1_5'),'allow_na',coalesce((v_item->>'na')::boolean,false)));
   END LOOP;
   IF (SELECT count(*) FROM public.feedback_template_questions WHERE version_id=v_version) <> 30 THEN
     RAISE EXCEPTION 'Unexpected question count in draft for %',v_t.program_key;
   END IF;
 END LOOP;
END $feedback_draft$;
